			dw kw_ltov, -3, arr_board+80
			dw kw_ltov, -2, arr_board+96
			dw kw_ltov, -4, arr_board+112

			; ISOChess.bas 193: For x = 0 To 7
			dw kw_ztov, var_initgame_x
for6_t:

			; ISOChess.bas 194: Board(x, 1) = -PAWN
