			; ISOChess.bas 251: Dim k1 As Integer, k2 As Integer, k3 As Integer, k4 As Integer, m As Integer

			; ISOChess.bas 252: col = TileCol(c, r)
			dw p_tilecol_c, var_rendertile_c, var_rendertile_r
			dw kw_vtov, var_tilecol_tilecol, var_rendertile_col

			; ISOChess.bas 253: row = TileRow(c, r)
			dw p_tilerow_c, var_rendertile_c, var_rendertile_r
			dw kw_vtov, var_tilerow_tilerow, var_rendertile_row

			; ISOChess.bas 254: p = Board(c, r)
			dw kw_mulvl, var_rendertile_c, 8, tmp0
			dw kw_add, tmp0, var_rendertile_r, tmp0
			dw kw_aget, arr_board, tmp0, var_rendertile_p

			; ISOChess.bas 255: shade = 0
			dw kw_ztov, var_rendertile_shade

