			dw kw_andvl, tmp0, 1, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse, if10_1
			dw kw_ltov, 8, var_rendertile_shade
if10_1:

			; ISOChess.bas 257: If p = EMPTY_SQ Then
