			dw if11_e_go
if11_1:

			; ISOChess.bas 261: Select Case Abs(p)
			dw kw_absv, var_rendertile_p, tmp0
			dw kw_vtov, tmp0, var_rendertile___sel12

			; ISOChess.bas 262: Case PAWN:   k1 = 135 : k2 = 4   : k3 = 129 : k4 = 130    '  .##. / #### on a ball
