			dw kw_goto_iffalse, sel12_1
sel12_b1:
			dw kw_ltov, 135, var_rendertile_k1
			dw kw_ltov, 4, var_rendertile_k2
			dw kw_ltov, 129, var_rendertile_k3
			dw kw_ltov, 130, var_rendertile_k4

			; ISOChess.bas 263: Case ROOK:   k1 = 130 : k2 = 129 : k3 = 129 : k4 = 130    ' #..# battlements
