			dw kw_ltov, 129, var_rendertile_k3
			dw kw_ltov, 130, var_rendertile_k4

			; ISOChess.bas 265: Case BISHOP: k1 = 129 : k2 = 131 : k3 = 129 : k4 = 130    ' .#.. a mitre
