			dw kw_goto_iffalse, sel12_4
sel12_b4:
			dw kw_ltov, 129, var_rendertile_k1
			dw kw_ltov, 131, var_rendertile_k2
			dw kw_ltov, 129, var_rendertile_k3
			dw kw_ltov, 130, var_rendertile_k4

			; ISOChess.bas 266: Case QUEEN:  k1 = 134 : k2 = 6   : k3 = 129 : k4 = 130    ' #..# crown points
			dw sel12_e_go
sel12_4:
			dw kw_cpeqvl, var_rendertile___sel12, 5
			dw kw_goto_iffalse, sel12_5
sel12_b5:
			dw kw_ltov, 134, var_rendertile_k1
			dw kw_ltov, 6, var_rendertile_k2
			dw kw_ltov, 129, var_rendertile_k3
			dw kw_ltov, 130, var_rendertile_k4

			; ISOChess.bas 267: Case KING:   k1 = 129 : k2 = 130 : k3 = 129 : k4 = 130    ' .##. a cross
			dw sel12_e_go
sel12_5:
			dw kw_cpeqvl, var_rendertile___sel12, 6
			dw kw_goto_iffalse, sel12_6
sel12_b6:
			dw kw_ltov, 129, var_rendertile_k1
			dw kw_ltov, 130, var_rendertile_k2
			dw kw_ltov, 129, var_rendertile_k3
