fn_zx_put:		; sub put (asm keyword), Zx.cls line 34
            pop hl		; Zx.cls 35
            ld c, (hl)              ; x [36]
            pop hl		; Zx.cls 37
            ld a, (hl)              ; y [38]
            pop de                  ; code's address [39]
            ld l, a                 ; the cell: ntc_dfile + 1 + y * 33 + x [40]
            ld h, 0		; Zx.cls 41
            ld b, h		; Zx.cls 42
            add hl, hl		; Zx.cls 43
            add hl, hl		; Zx.cls 44
            add hl, hl		; Zx.cls 45
            add hl, hl		; Zx.cls 46
            add hl, hl		; Zx.cls 47
            add hl, bc		; Zx.cls 48
            ld b, a		; Zx.cls 49
            ld c, b		; Zx.cls 50
            ld b, 0		; Zx.cls 51
            add hl, bc		; Zx.cls 52
            ld bc, ntc_dfile + 1		; Zx.cls 53
            add hl, bc		; Zx.cls 54
            ld a, (de)		; Zx.cls 55
            and #BF		; Zx.cls 56
            ld (hl), a		; Zx.cls 57
			ret			; end of #asm

fn_keys_down:		; function down (asm keyword), Keys.cls line 76
            pop hl		; Keys.cls 77
            ld e, (hl)		; Keys.cls 78
            inc hl		; Keys.cls 79
            ld d, (hl)		; Keys.cls 80
