            or a		; Keys.cls 82
            jr nz, fn_keys_down_kdno		; Keys.cls 83
            ld a, e		; Keys.cls 84
            cp 64		; Keys.cls 85
            jr nc, fn_keys_down_kdno		; Keys.cls 86
            and 7		; Keys.cls 87
            cp 5		; Keys.cls 88
            jr nc, fn_keys_down_kdno		; Keys.cls 89
            inc a		; Keys.cls 90
            ld d, a                 ; D = bit + 1 [91]
            ld a, e		; Keys.cls 92
            rrca		; Keys.cls 93
            rrca		; Keys.cls 94
            rrca		; Keys.cls 95
            and 7		; Keys.cls 96
            ld c, a		; Keys.cls 97
