			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_aget8
;kw_aget8, <arraybase>, <indexvar>, <destvar>  - Byte array element (0 .. 255)
kw_aget8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_aset8
;kw_aset8, <arraybase>, <indexvar>, <sourcevar>  - set a Byte array element (low byte)
kw_aset8:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld a, (hl)
			ld (de), a
			ret

;## kw_asetl
;kw_asetl, <arraybase>, <indexvar>, <literal>
kw_asetl:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			pop bc
			ld (hl), c
			inc hl
			ld (hl), b
			ret

; ============================================================
; Random (16 bit xorshift 7,9,8 - period 65535)
; ============================================================

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_seedv ntc_rnd_seed kw_seedl
;kw_seedv, <var>  - RANDOMIZE var (0 becomes 1)
kw_seedv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			jr ntc_seed

;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			pop hl
ntc_seed:
			ld a, h
			or l
			jr nz, ntc_seed_ok
			inc l
ntc_seed_ok:
			ld (ntc_rnd_seed), hl
			ret

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; Functions that build a string write into a temp, so they cut at
; NTC_STRMAX (the longest string in the program, set by the compiler);
; kw_strcpy / kw_strcat / input cut at the destination's capacity.
; ============================================================

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - tick count from the platform (CPC: interrupts, 300 a second,
;  only moving in normal mode)
kw_ticks:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_tk_got
			jp ntc_plat_ticks
ntc_tk_got:
			ex de, hl
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; String functions. Numbers are passed as the address of a word
; (a literal goes in as lit_n, a dw in the data). Results go to a
; string buffer (41 bytes). Dest may be the same as the source.
; ============================================================

;## ntc_fmt ntc_data
; Format$ with a number pattern. ntc_fmbuf holds "-123" (ntc_itoa / ntc_ltoa);
; the thread has <mindigits>, <group>, <prefix>, <suffix>. Writes to (ntc_fmd).
ntc_fm_common:
			pop bc
			ld a, c
			ld (ntc_fmmin), a
			pop bc
			ld a, c
			ld (ntc_fmgrp), a
			pop hl
			ld (ntc_fmpre), hl
			pop hl
			ld (ntc_fmsuf), hl
			ld de, (ntc_fmd)
			ld hl, ntc_fmbuf
			ld a, (hl)
			cp '-'
			jr nz, ntc_fm_pos
			ld (de), a
			inc de
			inc hl
ntc_fm_pos:
			ld (ntc_fmdig), hl
			ld hl, (ntc_fmpre)
ntc_fm_pre:
			ld a, (hl)
			or a
			jr z, ntc_fm_cnt
			ld (de), a
			inc de
			inc hl
			jr ntc_fm_pre
ntc_fm_cnt:
			ld hl, (ntc_fmdig)
			ld b, 0
ntc_fm_c1:
			ld a, (hl)
			or a
			jr z, ntc_fm_c2
			inc hl
			inc b
			jr ntc_fm_c1
ntc_fm_c2:
			ld c, 0
			ld a, (ntc_fmmin)
			sub b
			jr c, ntc_fm_c3
			ld c, a
ntc_fm_c3:
			ld a, b
			add a, c
			ld (ntc_fmk), a
ntc_fm_mod:
			cp 4
			jr c, ntc_fm_m2
			sub 3
			jr ntc_fm_mod
ntc_fm_m2:
			ld (ntc_fmm), a
			ld hl, (ntc_fmdig)
ntc_fm_out:
			ld a, (ntc_fmk)
			or a
			jr z, ntc_fm_suf
			ld a, c
			or a
			jr z, ntc_fm_d
			dec c
			ld a, '0'
			jr ntc_fm_put
ntc_fm_d:
			ld a, (hl)
			inc hl
ntc_fm_put:
			ld (de), a
			inc de
			ld a, (ntc_fmk)
			dec a
			ld (ntc_fmk), a
			ld a, (ntc_fmm)
			dec a
			ld (ntc_fmm), a
			jr nz, ntc_fm_out
			ld a, 3
			ld (ntc_fmm), a
			ld a, (ntc_fmk)
			or a
			jr z, ntc_fm_suf
			ld a, (ntc_fmgrp)
			or a
			jr z, ntc_fm_out
			ld a, ','
			ld (de), a
			inc de
			jr ntc_fm_out
ntc_fm_suf:
			ld hl, (ntc_fmsuf)
ntc_fm_s1:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			or a
			jr nz, ntc_fm_s1
			ret
ntc_fmd:		dw 0
ntc_fmdig:		dw 0
ntc_fmpre:		dw 0
ntc_fmsuf:		dw 0
ntc_fmmin:		db 0
ntc_fmgrp:		db 0
ntc_fmk:		db 0
ntc_fmm:		db 0
ntc_fmbuf:		ds 14

;## kw_strfmt ntc_fmt ntc_itoa
;kw_strfmt, <dest>, <var>, <mindigits>, <group>, <prefix>, <suffix>  - Format$(n, "0,000")
kw_strfmt:
			pop hl
			ld (ntc_fmd), hl
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_fmbuf
			ld ix, ntc_fm_common
			jp ntc_itoa

;## kw_strchr
;kw_strchr, <dest>, <nvar>  - Chr$(n)
kw_strchr:
			pop de
			pop hl
			ld a, (hl)
			ld (de), a
			inc de
			xor a
			ld (de), a
			ret

;## kw_strcstr ntc_itoa
;kw_strcstr, <dest>, <nvar>  - number to text (CStr, "x" & n)
kw_strcstr:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld ix, ntc_next
			jp ntc_itoa

;## ntc_ldata
ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_itol
;kw_l_itol, <intvar>, <dest>  - Integer to Long (sign extended)
kw_l_itol:
			pop hl
			pop de
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			ld a, (hl)
			ld (de), a
			inc de
			rla
			sbc a, a
			ld (de), a
			inc de
			ld (de), a
			ret

;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			pop hl
			pop de
			ldi
			ldi
			ret

;## kw_l_sub
;kw_l_sub, <a>, <b>, <dest>  - a - b
kw_l_sub:
			pop de
			pop hl
			pop ix
			ld a, (de)
			sub (hl)
			ld (ix+0), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ix+3), a
			ret

;## ntc_lcmp ntc_ldata
; DE = a, HL = b: work out a - b. ntc_lsgn = #80 if a < b (signed),
; ntc_lcnt = 0 if a = b. jp (ix) back.
ntc_lcmp:
			ld a, (de)
			sub (hl)
			ld (ntc_lr), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lr+3), a
			ld b, 0
			jp po, ntc_lcm_nov
			ld b, #80
ntc_lcm_nov:
			xor b
			and #80
			ld (ntc_lsgn), a
			ld hl, ntc_lr
			ld a, (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			inc hl
			or (hl)
			ld (ntc_lcnt), a
			jp (ix)

;## kw_l_cplt ntc_lcmp
;kw_l_cplt, <a>, <b>  - Z if a < b
kw_l_cplt:
			pop de
			pop hl
			ld ix, ntc_lclt
			jp ntc_lcmp
ntc_lclt:
			ld a, (ntc_lsgn)
			xor #80
			ret

;## kw_l_cpge ntc_lcmp
;kw_l_cpge, <a>, <b>  - Z if a >= b
kw_l_cpge:
			pop de
			pop hl
			ld ix, ntc_lcge
			jp ntc_lcmp
ntc_lcge:
			ld a, (ntc_lsgn)
			or a
			ret

;## ntc_lmul ntc_ldata
; ntc_la * ntc_lb -> ntc_lr (low 32 bits, same signed / unsigned). jp (ix)
ntc_lmul:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_lm_loop:
			ld hl, ntc_lb+3
			srl (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			dec hl
			rr (hl)
			jr nc, ntc_lm_skip
			ld de, ntc_la
			ld hl, ntc_lr
			ld a, (de)
			add a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
			inc de
			inc hl
			ld a, (de)
			adc a, (hl)
			ld (hl), a
ntc_lm_skip:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			djnz ntc_lm_loop
			jp (ix)

;## ntc_lnegm
; HL = address of a Long: negate it in place. jp (ix)
ntc_lnegm:
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			jp (ix)

;## ntc_ldiv ntc_ldata ntc_lnegm
; ntc_la / ntc_lb signed, truncating: quotient in ntc_la, remainder (with
; the dividend's sign) in ntc_lr. Divide by 0: quotient 0, remainder =
; dividend. jp (ix) back.
ntc_ldiv:
			ld (ntc_lix), ix
			ld hl, (ntc_lb)
			ld a, h
			or l
			ld hl, (ntc_lb+2)
			or h
			or l
			jr nz, ntc_ld_nz
			ld hl, (ntc_la)
			ld (ntc_lr), hl
			ld hl, (ntc_la+2)
			ld (ntc_lr+2), hl
			ld hl, 0
			ld (ntc_la), hl
			ld (ntc_la+2), hl
			jp ntc_ld_out
ntc_ld_nz:
			ld a, (ntc_la+3)
			ld (ntc_lsgn), a
			ld b, a
			ld a, (ntc_lb+3)
			xor b
			ld (ntc_lcnt), a
			ld a, (ntc_la+3)
			or a
			jp p, ntc_ld_apos
			ld hl, ntc_la
			ld ix, ntc_ld_apos
			jp ntc_lnegm
ntc_ld_apos:
			ld a, (ntc_lb+3)
			or a
			jp p, ntc_ld_bpos
			ld hl, ntc_lb
			ld ix, ntc_ld_bpos
			jp ntc_lnegm
ntc_ld_bpos:
			ld hl, 0
			ld (ntc_lr), hl
			ld (ntc_lr+2), hl
			ld b, 32
ntc_ld_loop:
			ld hl, ntc_la
			sla (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld hl, ntc_lr
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			inc hl
			rl (hl)
			ld de, ntc_lr
			ld hl, ntc_lb
			ld a, (de)
			sub (hl)
			ld (ntc_lt), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+1), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+2), a
			inc hl
			inc de
			ld a, (de)
			sbc a, (hl)
			ld (ntc_lt+3), a
			jr c, ntc_ld_no
			ld hl, (ntc_lt)
			ld (ntc_lr), hl
			ld hl, (ntc_lt+2)
			ld (ntc_lr+2), hl
			ld hl, ntc_la
			set 0, (hl)
ntc_ld_no:
			djnz ntc_ld_loop
			ld a, (ntc_lcnt)
			or a
			jp p, ntc_ld_qpos
			ld hl, ntc_la
			ld ix, ntc_ld_qpos
			jp ntc_lnegm
ntc_ld_qpos:
			ld a, (ntc_lsgn)
			or a
			jp p, ntc_ld_out
			ld hl, ntc_lr
			ld ix, ntc_ld_out
			jp ntc_lnegm
ntc_ld_out:
			ld ix, (ntc_lix)
			jp (ix)

;## kw_l_mul ntc_lmul ntc_ldata
;kw_l_mul, <a>, <b>, <dest>  - a * b
kw_l_mul:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			ld ix, ntc_lmu_back
			jp ntc_lmul
ntc_lmu_back:
			ld hl, ntc_lr
; copy the 4 bytes at HL to (ntc_ldst), then next keyword
ntc_lstore:
			ld de, (ntc_ldst)
			ldi
			ldi
			ldi
			ldi
			ret

;## kw_l_div ntc_ldiv kw_l_mul
;kw_l_div, <a>, <b>, <dest>  - a \ b
kw_l_div:
			ld ix, ntc_ldv_back
ntc_ldv_go:
			pop hl
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld de, ntc_lb
			ldi
			ldi
			ldi
			ldi
			pop hl
			ld (ntc_ldst), hl
			jp ntc_ldiv
ntc_ldv_back:
			ld hl, ntc_la
			jp ntc_lstore

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 32			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_sinit:		db 0			; 1 once the screen is set up (D_FILE points at ntc_dfile)
ntc_zxkeys:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF	; the half rows at the last frame (bits 0-4, 0 = down)
ntc_zxkprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF	; the frame before (Inkey: new presses)
ntc_kidx:		db 0			; key index found by the scan
ntc_klink:		dw 0			; return for ntc_plat_getkey / scankey
ntc_frsp:		dw 0			; the thread's SP while a frame is drawn
ntc_frix:		dw 0			; the frame's return
; the display file: a HALT, then 24 rows of 32 codes and a HALT (793 bytes). Executed
; from #C000 + (its address - #4000) while a frame is drawn: every code must have bit 6
; clear (0-63, 128-191), or the Z80 runs it as an instruction
ntc_dfile:		db #76
				DUP 24
				ds 32, 0
				db #76
				EDUP
ntc_dfend:

; ASCII 32-127 -> ZX81 codes (the ZX81 has no lower case: a-z print as A-Z; what it
; hasn't got prints as ?)
ntc_ascmap:
				db 0, 15, 11, 15, 13, 15, 15, 11		;  ! " # $ % & '
				db 16, 17, 23, 21, 26, 22, 27, 24		; ( ) * + , - . /
				db 28, 29, 30, 31, 32, 33, 34, 35		; 0-7
				db 36, 37, 14, 25, 19, 20, 18, 15		; 8 9 : ; < = > ?
				db 15, 38, 39, 40, 41, 42, 43, 44		; @ A-G
				db 45, 46, 47, 48, 49, 50, 51, 52		; H-O
				db 53, 54, 55, 56, 57, 58, 59, 60		; P-W
				db 61, 62, 63, 16, 24, 17, 15, 22		; X Y Z [ \ ] ^ _
				db 11, 38, 39, 40, 41, 42, 43, 44		; ` a-g
				db 45, 46, 47, 48, 49, 50, 51, 52		; h-o
				db 53, 54, 55, 56, 57, 58, 59, 60		; p-w
				db 61, 62, 63, 16, 14, 17, 22, 15		; x y z { | } ~ DEL

;## ntc_plat_screen ntc_plat_data ntc_data ntc_plat_scroll
; ------------------------------------------------------------
; ntc_plat_putc - A = character: ASCII 32-127 through ntc_ascmap, anything
; else as a ZX81 code; write it at the cursor, move on
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_raw
			cp 128
			jr nc, ntc_pc_raw
			sub 32
			ld l, a
			ld h, 0
			ld de, ntc_ascmap
			add hl, de
			ld a, (hl)
ntc_pc_raw:
			and #BF				; (bit 6 clear: never an instruction in the display file)
			ld c, a
			ld a, (ntc_cury)
			ld l, a
			ld h, 0
			ld e, l
			ld d, h
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, de			; row * 33
			ld a, (ntc_curx)
			ld e, a
			add hl, de
			ld de, ntc_dfile + 1
			add hl, de
			ld (hl), c
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp 32
			jr z, ntc_pc_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pc_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 24
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_scroll ntc_plat_data ntc_data
; ------------------------------------------------------------
; ntc_plat_scroll - rows 1-23 up one (33 bytes each: the HALTs move with
; them), row 23 cleared, cursor on it
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, 23
			ld (ntc_cury), a
			ld hl, ntc_dfile + 1 + 33
			ld de, ntc_dfile + 1
			ld bc, 23 * 33
			ldir
			ld hl, ntc_dfile + 1 + 23 * 33
			ld d, h
			ld e, l
			inc de
			ld (hl), 0
			ld bc, 31
			ldir
			jp (ix)

;## ntc_plat_cls @unit ntc_plat_data ntc_data
; ------------------------------------------------------------
; ntc_plat_cls - the display file written afresh (spaces, the HALTs),
; cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ntc_dfile
			ld (hl), #76
			inc hl
			ld b, 24
ntc_cl_row:
			ld c, 32
ntc_cl_col:
			ld (hl), 0
			inc hl
			dec c
			jr nz, ntc_cl_col
			ld (hl), #76
			inc hl
			djnz ntc_cl_row
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_mode @unit ntc_plat_cls ntc_plat_data ntc_data
; ------------------------------------------------------------
; ntc_plat_mode - A = mode (ignored: one mode). The first time: the ROM's
; D_FILE / DF_CC point at ntc_dfile (so the ROM shows this screen after
; End). Then clear
; ------------------------------------------------------------
ntc_plat_mode:
			ld a, (ntc_sinit)
			or a
			jr nz, ntc_md_set
			inc a
			ld (ntc_sinit), a
			ld hl, ntc_dfile
			ld (#400C), hl			; D_FILE
			inc hl
			ld (#400E), hl			; DF_CC
ntc_md_set:
			jp ntc_plat_cls

;## ntc_plat_locate @unit ntc_plat_data ntc_data
; ------------------------------------------------------------
; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
; ------------------------------------------------------------
ntc_plat_locate:
			xor a
			ld (ntc_wrapped), a
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			cp 32
			jr c, ntc_lc_xmax
			ld a, 31
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 24
			jr c, ntc_lc_ymax
			ld a, 23
ntc_lc_ymax:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_zxframe ntc_plat_data ntc_data
; ------------------------------------------------------------
; ntc_zx_frame - one television frame, as the ROM's FAST mode draws one:
;   - the vertical sync pulse (an IN from port #FE starts it, any OUT ends
;     it): the 8 keyboard half rows are read into ntc_zxkeys meanwhile, then
;     a wait, so the pulse is about 400us
;   - 55 blank lines: a HALT run with C = 55 lines, B = 1
;   - the 24 rows: B = 25 (the display file's leading HALT and 24 rows),
;     C = 1 (the first interrupt after the leading HALT, then 8 a row)
;   - 55 blank lines again
; Each part is a call to ntc_zx_d5 (the ROM's DISPLAY-5): R loaded so the
; interrupt (R's bit 6 going low) comes at the end of a 32 character line,
; interrupts on, jump into the display file's echo at #C000+. The ROM's
; interrupt routine at #38 runs from there: counts the lines (C), moves
; to the next row (POP HL: the address after the HALT), counts the rows
; (B), and RET Z brings it back here when they are done - so SP must be
; the real stack. Interrupts are off again when it returns. IX is kept.
; Counts ntc_ticks. Entered with jp, back with jp (ix).
; ------------------------------------------------------------
ntc_zx_frame:
			ld (ntc_frsp), sp
			ld sp, (ntc_csp)
			ld (ntc_frix), ix
			ld hl, (ntc_ticks)
			inc hl
			ld (ntc_ticks), hl
			ld a, #1E				; the ROM's character table at #1E00
			ld i, a
			im 1
			ld hl, ntc_zxkeys			; the vertical sync: the keyboard read during it
			ld bc, #FEFE			; half row 0 (A8 low) ... 7 (A15 low)
ntc_zx_kl:
			in a, (c)
			ld (hl), a
			inc hl
			rlc b
			jr c, ntc_zx_kl
			ld b, 80
ntc_zx_vs:
			djnz ntc_zx_vs			; the pulse about 400us in all
			out (#FF), a			; the end of the vertical sync
			ld hl, ntc_dfile + #8000	; the leading HALT, in the echo
			ld c, 55				; the top margin: 55 blank lines
			ld a, #FC
			ld b, 1
			call ntc_zx_d5
			dec hl					; (POP HL gave the address after the HALT)
			ld bc, #1901			; the rows: B = 25, C = 1
			ld a, #F5
			call ntc_zx_d5
			dec hl					; the last HALT
			ld c, 55				; the bottom margin
			ld a, #FC
			ld b, 1
			call ntc_zx_d5
ntc_zx_fend:						; (the test harness: the frame is drawn)
			ld ix, (ntc_frix)
			ld sp, (ntc_frsp)
			jp (ix)
ntc_zx_d5:
			ld r, a
			ld a, #DD
			ei
			jp (hl)

;## ntc_plat_key ntc_plat_data ntc_data ntc_plat_zxframe
; ------------------------------------------------------------
; ntc_plat_scankey - draws a frame (the keyboard is read during its
; vertical sync), A = ASCII of a key pressed since the last scan, 0 if
; none
; ------------------------------------------------------------
ntc_plat_scankey:
			ld (ntc_klink), ix
			ld ix, ntc_ks_back
			jp ntc_zx_frame
ntc_ks_back:
			ld a, #FF
			ld (ntc_kidx), a
			ld hl, ntc_zxkeys
			ld de, ntc_zxkprev
			ld iy, ntc_kign
			ld bc, #0800			; B = 8 half rows, C = key index
ntc_ks_find:
			ld a, (ntc_kidx)
			inc a
			jr nz, ntc_ks_next
			ld a, (hl)
			cpl
			ex de, hl
			and (hl)				; down now, up last scan
			ex de, hl
			and (iy+0)				; not shift on its own
			jr z, ntc_ks_next
ntc_ks_bit:
			rrca
			jr c, ntc_ks_got
			inc c
			jr ntc_ks_bit
ntc_ks_got:
			ld a, c
			ld (ntc_kidx), a
ntc_ks_next:
			ld a, c
			and #F8
			add a, 8
			ld c, a
			inc hl
			inc de
			inc iy
			djnz ntc_ks_find
			ld hl, ntc_zxkeys
			ld de, ntc_zxkprev
			ld bc, 8
			ldir
			ld a, (ntc_kidx)
			cp #FF
			jr z, ntc_ks_none
			ld e, a
			ld d, 0
			ld hl, ntc_keymap
			ld a, (ntc_zxkeys)
			rrca					; shift (half row 0, bit 0)
			jr c, ntc_ks_map
			ld hl, ntc_keymaps
ntc_ks_map:
			add hl, de
			ld a, (hl)
			ld ix, (ntc_klink)
			jp (ix)
ntc_ks_none:
			xor a
			ld ix, (ntc_klink)
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_getkey - frames until a key is pressed, A = ASCII
; ------------------------------------------------------------
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_scan:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr z, ntc_gk_scan
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

; keys that never count as a press on their own (shift: half row 0 bit 0)
ntc_kign:		db #1E, #1F, #1F, #1F, #1F, #1F, #1F, #1F

; half row 0-7, bit 0-4 -> ASCII (0 = ignored); 8 a row
ntc_keymap:
			db 0, "z", "x", "c", "v", 0, 0, 0			; shift z x c v
			db "a", "s", "d", "f", "g", 0, 0, 0
			db "q", "w", "e", "r", "t", 0, 0, 0
			db "1", "2", "3", "4", "5", 0, 0, 0
			db "0", "9", "8", "7", "6", 0, 0, 0
			db "p", "o", "i", "u", "y", 0, 0, 0
			db 13, "l", "k", "j", "h", 0, 0, 0		; newline l k j h
			db " ", ".", "m", "n", "b", 0, 0, 0
ntc_keymaps:									; with shift: the ZX81's symbols where it has them
			db 0, ":", ";", "?", "/", 0, 0, 0
			db "A", "S", "D", "F", "G", 0, 0, 0
			db "Q", "W", "E", "R", "T", 0, 0, 0
			db 27, "2", "3", "4", 8, 0, 0, 0			; edit (ESC) 2 3 4 left (backspace)
			db 127, "9", "8", 9, "6", 0, 0, 0		; rubout (DEL) 9 8 right (TAB) 6
			db 34, ")", "(", "$", ">", 0, 0, 0		; " ) ( $ >
			db 13, "=", "+", "-", "^", 0, 0, 0		; function (newline) = + - **
			db 27, ",", ">", "<", "*", 0, 0, 0		; break (ESC) , > < *

;## ntc_plat_frame ntc_plat_zxframe
; ------------------------------------------------------------
; ntc_plat_frame - Frame: draw one frame
; ------------------------------------------------------------
ntc_plat_frame:
			jp ntc_zx_frame

;## ntc_plat_ticks ntc_data
; ------------------------------------------------------------
; ntc_plat_ticks - HL = frames drawn
; ------------------------------------------------------------
ntc_plat_ticks:
			ld hl, (ntc_ticks)
			jp (ix)

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - before returning to the ROM (USR): nothing to undo.
; The ROM shows ntc_dfile (D_FILE) in its FAST mode input loop.
; ------------------------------------------------------------
ntc_plat_exit:
			jp (ix)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #8000 (RAMTOP of a 16K ZX81; the ROM's stack is just under it). Called
; on the real stack (call / ret), only by the Memory class.
ntc_plat_memtop:
			ld hl, #8000
			ret


ntc_end:				; the end of the program (and of its file)
; ZX81: the rest of the BASIC program round the code, for the ROM (zx81Tail)
zx_rem_end:		db #76			; the end of line 1 (REM: the program)
zx_line2:		db 0, 2			; line 2: RAND USR 16514
			dw zx_l2end - zx_l2start
zx_l2start:		db #F9, #D4		; RAND USR
			db 29, 34, 33, 29, 32		; "16514"
			db #7E, #8F, #01, #04, #00, #00	; its value
			db #76
zx_l2end:
zx_dfile:		ds 25, #76		; a collapsed display file for the ROM (NTC draws its own)
zx_vars:		db #80			; no variables
zx_eline:		db #76, #76		; the edit line
zx_stk:					; the calculator stack (STKBOT, STKEND: the ROM evaluates the USR address on it)
ntc_zxend:				; the end of the .P file (the arrays from here)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_zxend		; after the ROM's part of the .P file (zx81Tail)
ntc_bss		equ ntc_bssfrom
arr_board		equ ntc_bss + 0		; 128 bytes
arr_validmap		equ ntc_bss + 128		; 64 bytes
ntc_bss_size	equ 192
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables

; ============================================================
; ZX81: the system variables and the start of line 1 (REM), before the program, and
; the .P file - #4009 up to the arrays (zx81Head)
; ============================================================
			ASSERT ntc_free <= #7F00, "the program and its arrays must end below #7F00 (16K: the ROM's stack is under #8000)"
			org #4009
zx_sysvars:
			db 0				; #4009 VERSN
			dw 2				; #400A E_PPC: the current line
			dw zx_dfile			; #400C D_FILE
			dw zx_dfile + 1		; #400E DF_CC
			dw zx_vars			; #4010 VARS
			dw 0				; #4012 DEST
			dw zx_eline			; #4014 E_LINE
			dw zx_eline + 1		; #4016 CH_ADD
			dw 0				; #4018 X_PTR
			dw zx_stk			; #401A STKBOT
			dw zx_stk			; #401C STKEND
			db 0				; #401E BERG
			dw #405D			; #401F MEM: MEMBOT
			db 0				; #4021
			db 2				; #4022 DF_SZ
			dw 2				; #4023 S_TOP
			db #FF, #FF			; #4025 LAST_K
			db 0				; #4027 DEBOUNCE
			db 55				; #4028 MARGIN (55: a 50Hz machine)
			dw zx_line2			; #4029 NXTLIN: the line to run next - RAND USR, as soon as the program has loaded
			dw 0				; #402B OLDPPC
			db 0				; #402D FLAGX
			dw 0				; #402E STRLEN
			dw #0C8D			; #4030 T_ADDR
			dw 0				; #4032 SEED
			dw 0				; #4034 FRAMES
			dw 0				; #4036 COORDS
			db #BC				; #4038 PR_CC
			db #21, #18			; #4039 S_POSN
			db 0				; #403B CDFLAG: FAST (bits 6, 7 clear: the NMI generator stays off)
			ds 32, 0			; #403C PRBUFF
			db #76
			ds 30, 0			; #405D MEMBOT
			dw 0				; #407B
			ASSERT $ == #407D, "the ZX81 system variables must end at #407D"
zx_line1:		db 0, 1			; line 1: REM, its text the program
			dw zx_rem_end - ntc_start + 2	; (the REM token, the program, the NEWLINE)
			db #EA				; REM
			ASSERT $ == ntc_start, "the program must start at the REM's text (org #4082)"
			SAVEBIN "ISOCHESS.P", #4009, ntc_zxend + 1 - #4009